import { Component, EventEmitter, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { FormControl, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { NgxIntlTelInputModule } from 'ngx-intl-tel-input';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { CommonModule } from '@angular/common';
import { HelpcenterService } from '../../../../shared/services/helpcenter/helpcenter.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
@Component({
  selector: 'moduleform',
  standalone: true,
  imports: [CommonModule, IconComponent, NgxIntlTelInputModule, FormsModule,
    ReactiveFormsModule, MatFormFieldModule, MatSelectModule, ButtonComponent
  ],
  templateUrl: './moduleform.component.html',
  styleUrl: './moduleform.component.scss'
})
export class ModuleformComponent {
  @Input() curruntmodule: boolean = false;
  @Input() selectedmodule: any;
  @Output() moduleupdated = new EventEmitter<any>();
  permission: string = 'N';
  curruntsubmodule: any;
  tags: any[] = [];
  frm: any;
  validation_messages: any;
  formsubmit: boolean = false;
  active_forms: any = '';
  nCaseid: any;
  role_list: any;
  company_list: any;
  profileUrl: any = '';
  @Input() issubmodule: boolean = false;
  constructor(private helpcenterService: HelpcenterService, private toastr: TostbarService) {
    this.validation_messages = {
      'nChid': [
        { type: 'required', message: 'Chapter is required' }
      ]
    }
  }
  ngOnInit(): void {
    this.frm = new FormGroup({
      cTitle: new FormControl('', Validators.required),
      cDescription: new FormControl(''),
      cLink: new FormControl(''),
    });



  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['selectedmodule']) {
      debugger;
      if (this.selectedmodule) {
        this.helpcenterService.getsubmodule_detail(this.selectedmodule).then((res: any) => {
          this.frm.patchValue(res);
          this.curruntsubmodule = res;
          this.permission = 'E';
          this.tags = res.jTags;
        });
      }
      else {
        this.frm.reset();
        this.permission = 'N';
        this.tags = [];
      }
    }
  }



  onsubmit() {
    debugger;
    this.formsubmit = true;
    if (this.frm.invalid) {
      return;
    }
    let mdl: any = {};
    mdl.nSMid = this.selectedmodule || 0;
    mdl.nMainid = this.curruntmodule || 0;
    mdl.cTitle = this.frm.value.cTitle;
    mdl.cLink = this.frm.value.cLink;
    mdl.cDescription = this.frm.value.cDescription || 'no description';
    mdl.jTags = this.tags;
    mdl.cPermission = this.permission == 'E' ? 'U' : 'I';
    //send submodule id & parent id
    this.helpcenterService.sub_module_iu(mdl).then((res: any) => {

      if (res.msg == -1) {
        this.toastr.error(res.msg);
        return;
      }

      this.frm.reset();
      this.permission = 'N';
      this.tags = [];
      this.formsubmit = false;

      this.toastr.success(`Module ${this.permission == 'E' ? 'Updated' : 'Added'} successfully`);

      this.moduleupdated.emit(res);
    });
  }


  addtag(event: any) {
    if (event.key === 'Enter') {
      this.tags.push(event.target.value);
      event.target.value = '';
    }
  }

  removetag(tag: any) {
    this.tags = this.tags.filter((t: any) => t !== tag);
  }
}
